'use client';

import { useEffect, useRef, useState } from 'react';
import type { Map as MapLibreMap, GeoJSONSource } from 'maplibre-gl';
import { supabase } from '../lib/supabase';

type Country = { name: string; code: string };
const WORLD: [number, number] = [7, 24];
const WORLD_ZOOM = 1.45;
const countriesUrl = 'https://raw.githubusercontent.com/datasets/geo-countries/master/data/countries.geojson';

function geometryBounds(geometry: { coordinates: unknown }): [[number, number], [number, number]] {
  let west = 180, south = 90, east = -180, north = -90;
  const visit = (value: unknown): void => {
    if (!Array.isArray(value)) return;
    if (typeof value[0] === 'number' && typeof value[1] === 'number') {
      west = Math.min(west, value[0]); east = Math.max(east, value[0]);
      south = Math.min(south, value[1]); north = Math.max(north, value[1]);
      return;
    }
    value.forEach(visit);
  };
  visit(geometry.coordinates);
  return [[west, south], [east, north]];
}

export default function TravelMap() {
  const mapElement = useRef<HTMLDivElement>(null);
  const mapRef = useRef<MapLibreMap | null>(null);
  const selectionRequest = useRef(0);
  const worldCountries = useRef<unknown>(null);
  const activeCountryCode = useRef('');
  const [country, setCountry] = useState<Country | null>(null);
  const [ready, setReady] = useState(false);
  const [email, setEmail] = useState('');
  const [userId, setUserId] = useState<string | null>(null);
  const [authMessage, setAuthMessage] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    let map: MapLibreMap;
    let disposed = false;
    async function boot() {
      const maplibregl = await import('maplibre-gl');
      if (!mapElement.current || disposed) return;
      maplibregl.setWorkerUrl('/maplibre/maplibre-gl-worker.mjs');
      const key = process.env.NEXT_PUBLIC_MAPTILER_KEY;
      const style = key && key !== 'tu_clave_publica_de_maptiler'
        ? `https://api.maptiler.com/maps/streets-v2/style.json?key=${key}`
        : 'https://demotiles.maplibre.org/style.json';
      map = new maplibregl.Map({ container: mapElement.current, style, center: WORLD, zoom: WORLD_ZOOM, minZoom: 1.1, maxZoom: 18 });
      map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'top-right');
      mapRef.current = map;
      map.on('load', async () => {
        try {
          const response = await fetch(countriesUrl);
          if (!response.ok) throw new Error();
          const rawData = await response.json();
          const data = { ...rawData, features: rawData.features.map((item: Record<string, unknown>, index: number) => ({ ...item, id: index })) };
          worldCountries.current = data;
          map.addSource('countries', { type: 'geojson', data });
          map.addSource('country-highlight', { type: 'geojson', data: { type: 'FeatureCollection', features: [] } });
          map.addSource('admin-one', { type: 'geojson', data: { type: 'FeatureCollection', features: [] } });
          map.addSource('admin-two', { type: 'geojson', data: { type: 'FeatureCollection', features: [] } });
          map.addLayer({ id: 'countries-fill', type: 'fill', source: 'countries', paint: { 'fill-color': ['case', ['boolean', ['feature-state', 'hover'], false], '#f7b168', '#b7cfbe'], 'fill-opacity': ['case', ['boolean', ['feature-state', 'hover'], false], 0.42, 0.24] } });
          map.addLayer({ id: 'countries-outline', type: 'line', source: 'countries', paint: { 'line-color': ['case', ['boolean', ['feature-state', 'hover'], false], '#e85f3d', '#477467'], 'line-width': ['case', ['boolean', ['feature-state', 'hover'], false], 2.4, 0.8], 'line-opacity': 0.9 } });
          map.addLayer({ id: 'country-highlight-fill', type: 'fill', source: 'country-highlight', paint: { 'fill-color': '#f7b168', 'fill-opacity': 0.1 } });
          map.addLayer({ id: 'country-highlight-line', type: 'line', source: 'country-highlight', paint: { 'line-color': '#ec6f4d', 'line-width': 4, 'line-opacity': 1 } });
          map.addLayer({ id: 'admin-one-fill', type: 'fill', source: 'admin-one', paint: { 'fill-color': ['case', ['boolean', ['feature-state', 'hover'], false], '#f7b168', '#f7d7ab'], 'fill-opacity': ['case', ['boolean', ['feature-state', 'hover'], false], 0.32, 0.08] } });
          map.addLayer({ id: 'admin-one-line', type: 'line', source: 'admin-one', paint: { 'line-color': ['case', ['boolean', ['feature-state', 'hover'], false], '#e85f3d', '#fffaf0'], 'line-width': ['case', ['boolean', ['feature-state', 'hover'], false], 3, 1.25] } });
          map.addLayer({ id: 'admin-two-fill', type: 'fill', source: 'admin-two', paint: { 'fill-color': ['case', ['boolean', ['feature-state', 'hover'], false], '#8ed4cd', '#c7e8e2'], 'fill-opacity': ['case', ['boolean', ['feature-state', 'hover'], false], 0.36, 0.06] } });
          map.addLayer({ id: 'admin-two-line', type: 'line', source: 'admin-two', paint: { 'line-color': ['case', ['boolean', ['feature-state', 'hover'], false], '#18877c', '#eafffc'], 'line-width': ['case', ['boolean', ['feature-state', 'hover'], false], 2.5, 1] } });
          map.on('mouseenter', 'countries-fill', () => map.getCanvas().style.cursor = 'pointer');
          map.on('mouseleave', 'countries-fill', () => map.getCanvas().style.cursor = '');
          let hoveredCountry: string | number | null = null;
          map.on('mousemove', 'countries-fill', (event) => {
            const id = event.features?.[0]?.id;
            if (hoveredCountry !== null) map.setFeatureState({ source: 'countries', id: hoveredCountry }, { hover: false });
            if (id !== undefined) map.setFeatureState({ source: 'countries', id }, { hover: true });
            hoveredCountry = id ?? null;
          });
          map.on('mouseleave', 'countries-fill', () => {
            if (hoveredCountry !== null) map.setFeatureState({ source: 'countries', id: hoveredCountry }, { hover: false });
            hoveredCountry = null;
          });
          map.on('click', 'countries-fill', async (event) => {
            const feature = event.features?.[0]; if (!feature) return;
            const name = String(feature.properties?.ADMIN || feature.properties?.name || 'Este país');
            const code = String(feature.properties?.ISO_A3 || '');
            setCountry({ name, code });
            activeCountryCode.current = code;
            const requestId = ++selectionRequest.current;
            // MapLibre entrega una instancia interna; el worker solo acepta GeoJSON plano.
            let selectedFeature = JSON.parse(JSON.stringify(feature));
            try {
              const boundary = await fetch(`/api/boundaries/${code}`).then((response) => {
                if (!response.ok) throw new Error('Boundary unavailable');
                return response.json();
              });
              if (requestId !== selectionRequest.current) return;
              selectedFeature = boundary.type === 'FeatureCollection' ? boundary.features[0] : boundary;
            } catch {
              // Si no hay frontera detallada disponible, se utiliza la frontera inicial.
            }
            if (requestId !== selectionRequest.current) return;
            (map.getSource('country-highlight') as GeoJSONSource).setData({ type: 'FeatureCollection', features: [selectedFeature] });
            const divisions = await fetch(`/api/boundaries/${code}?level=ADM1`).then((response) => response.ok ? response.json() : null);
            if (divisions && requestId === selectionRequest.current) {
              const features = divisions.features?.map((item: Record<string, unknown>, index: number) => ({ ...item, id: index })) ?? [];
              (map.getSource('admin-one') as GeoJSONSource).setData({ type: 'FeatureCollection', features });
            }
            const bounds = geometryBounds(selectedFeature.geometry as { coordinates: unknown });
            map.fitBounds(bounds, { padding: { top: 80, bottom: 70, left: 70, right: 70 }, maxZoom: 6, duration: 1100 });
          });
          let hoveredAdminOne: string | number | null = null;
          const setAdminOneHover = (id: string | number | undefined) => {
            if (hoveredAdminOne !== null) map.setFeatureState({ source: 'admin-one', id: hoveredAdminOne }, { hover: false });
            if (id !== undefined) map.setFeatureState({ source: 'admin-one', id }, { hover: true });
            hoveredAdminOne = id ?? null;
          };
          map.on('mousemove', 'admin-one-fill', (event) => { map.getCanvas().style.cursor = 'pointer'; setAdminOneHover(event.features?.[0]?.id); });
          map.on('mouseleave', 'admin-one-fill', () => { map.getCanvas().style.cursor = ''; setAdminOneHover(undefined); });
          let hoveredAdminTwo: string | number | null = null;
          const setAdminTwoHover = (id: string | number | undefined) => {
            if (hoveredAdminTwo !== null) map.setFeatureState({ source: 'admin-two', id: hoveredAdminTwo }, { hover: false });
            if (id !== undefined) map.setFeatureState({ source: 'admin-two', id }, { hover: true });
            hoveredAdminTwo = id ?? null;
          };
          map.on('mousemove', 'admin-two-fill', (event) => { map.getCanvas().style.cursor = 'pointer'; setAdminTwoHover(event.features?.[0]?.id); });
          map.on('mouseleave', 'admin-two-fill', () => { map.getCanvas().style.cursor = ''; setAdminTwoHover(undefined); });
          map.on('click', 'admin-one-fill', async (event) => {
            const region = event.features?.[0];
            if (!region || !activeCountryCode.current) return;
            const regionBounds = geometryBounds(region.geometry as { coordinates: unknown });
            const subdivisions = await fetch(`/api/boundaries/${activeCountryCode.current}?level=ADM2`).then((response) => response.ok ? response.json() : null);
            if (!subdivisions) return;
            const [southWest, northEast] = regionBounds;
            const features = (subdivisions.features ?? [])
              .filter((item: { geometry: { coordinates: unknown } }) => {
                const [candidateSouthWest, candidateNorthEast] = geometryBounds(item.geometry);
                const longitude = (candidateSouthWest[0] + candidateNorthEast[0]) / 2;
                const latitude = (candidateSouthWest[1] + candidateNorthEast[1]) / 2;
                return longitude >= southWest[0] && longitude <= northEast[0] && latitude >= southWest[1] && latitude <= northEast[1];
              })
              .map((item: Record<string, unknown>, index: number) => ({ ...item, id: index }));
            (map.getSource('admin-two') as GeoJSONSource).setData({ type: 'FeatureCollection', features });
            map.fitBounds(regionBounds, { padding: { top: 80, bottom: 70, left: 70, right: 70 }, maxZoom: 9, duration: 850 });
          });
          setReady(true);
        } catch { setReady(true); }
      });
    }
    boot();
    return () => { disposed = true; map?.remove(); };
  }, []);

  useEffect(() => {
    if (!supabase) return;
    supabase.auth.getUser().then(({ data }) => setUserId(data.user?.id ?? null));
    const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => setUserId(session?.user.id ?? null));
    return () => listener.subscription.unsubscribe();
  }, []);

  const reset = async () => {
    const map = mapRef.current; if (!map) return;
    selectionRequest.current += 1;
    activeCountryCode.current = '';
    (map.getSource('country-highlight') as GeoJSONSource)?.setData({ type: 'FeatureCollection', features: [] });
    (map.getSource('admin-one') as GeoJSONSource)?.setData({ type: 'FeatureCollection', features: [] });
    (map.getSource('admin-two') as GeoJSONSource)?.setData({ type: 'FeatureCollection', features: [] });
    map.flyTo({ center: WORLD, zoom: WORLD_ZOOM, duration: 1000 }); setCountry(null);
  };
  const locate = () => navigator.geolocation?.getCurrentPosition(({ coords }) => {
    mapRef.current?.flyTo({ center: [coords.longitude, coords.latitude], zoom: 10, duration: 900 });
  });
  const requestAccess = async () => {
    if (!supabase || !email) return;
    const { error } = await supabase.auth.signInWithOtp({ email, options: { emailRedirectTo: window.location.origin } });
    setAuthMessage(error ? 'No hemos podido enviar el enlace. Revisa el correo.' : 'Revisa tu correo para entrar en Reise.');
  };
  const saveTrip = async () => {
    if (!country) return;
    if (!supabase || !userId) { setAuthMessage('Inicia sesión para guardar este viaje.'); return; }
    setSaving(true);
    const { error } = await supabase.from('trips').insert({ owner_id: userId, title: `Viaje a ${country.name}`, country_code: country.code || 'XX' });
    setSaving(false);
    setAuthMessage(error ? 'No se ha podido guardar. ¿Ya ejecutaste schema.sql en Supabase?' : `${country.name} se ha guardado en tus viajes.`);
  };

  return <main className="reise">
    <section className="map-wrap" aria-label="Mapamundi interactivo"><div ref={mapElement} className="map" />
      <header className="top"><div className="brand"><b>R</b>reise</div><button className="location" onClick={locate} aria-label="Ir a mi ubicación">◎</button></header>
      <div className={`intro ${country ? 'hidden' : ''}`}><p className="eyebrow">EXPLORA EL MUNDO</p><h1>¿A dónde<br />vamos?</h1><p>Elige un país para descubrir sus rutas.</p></div>
      <div className="bottom-tools"><button className="pill primary" onClick={reset}>◉ &nbsp;Mapamundi</button>{country && <button className="pill" onClick={reset}>↶ &nbsp;Ver todos</button>}</div>
      <div className="notice">{ready ? (country ? 'Acércate para ver carreteras y caminos' : 'Selecciona un país para enfocarlo') : 'Cargando mapa…'}</div>
    </section>
    <aside className="panel"><header><p className="eyebrow">PLANIFICA SIN PRISA</p><h2>Tu próximo<br /><em>recorrido</em></h2></header><p className="panel-copy">Cada viaje empieza eligiendo un lugar.</p>
      <div className={`selected ${country ? 'active' : ''}`}><span className="symbol">{country ? '⌖' : '⌁'}</span><div><strong>{country?.name ?? 'Elige un país'}</strong><p>{country ? 'Seleccionado. Acércate para explorar sus carreteras y crear una ruta.' : 'Haz clic en el mapa para empezar a explorar.'}</p></div></div>
      {country && <button className="save" onClick={saveTrip} disabled={saving}>{saving ? 'Guardando…' : 'Guardar en mis viajes'}</button>}
      {!userId && <div className="access"><label htmlFor="email">Guarda tus rutas</label><div><input id="email" type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="tu@email.com" /><button onClick={requestAccess}>Entrar</button></div></div>}
      <p className="status">{authMessage || (country?.code ? `DESTINO · ${country.code}` : 'LISTO PARA EXPLORAR')}</p><footer className="footer"><span>REISE / 2026</span><span>01 — 01</span></footer>
    </aside>
  </main>;
}
